function enterScene(){
 if(!started||paused||!$('#modal').classList.contains('hidden'))return;
 formation?.cancel();keys.clear();resetJoy();target=null;closeContext();$('#floating-tip').style.display='none';viewMode=true;paused=true;
 world.viewLighting=game.state.phase==='night'?1:0;world.setSceneView('wide');document.body.classList.add('scene-view');$('#scene-toolbar').hidden=false;$('#scene-name').textContent=BIOMES[game.state.biome]?.name||'余烬棋城';$('#scene-light').textContent=world.viewLighting?'切换日景':'切换夜景';
 document.querySelectorAll('[data-scene-angle]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.sceneAngle==='wide')));$('#exit-scene').focus();
}
function leaveScene(){viewMode=false;paused=false;world.viewLighting=undefined;world.setSceneView(null);keys.clear();resetJoy();document.body.classList.remove('scene-view');$('#scene-toolbar').hidden=true;$('#view-scene').focus();}
$('#view-scene').onclick=enterScene;$('#exit-scene').onclick=leaveScene;
$('#scene-light').onclick=()=>{world.viewLighting=world.viewLighting?0:1;$('#scene-light').textContent=world.viewLighting?'切换日景':'切换夜景';};
$('#scene-toolbar').addEventListener('click',e=>{const b=e.target.closest('[data-scene-angle]');if(!b)return;world.setSceneView(b.dataset.sceneAngle);document.querySelectorAll('[data-scene-angle]').forEach(c=>c.setAttribute('aria-pressed',String(c===b)));});
